"""Импорт банковских выписок.

Поддерживаются три формата (определяются по заголовку):

    nova:        date,amount,description
                 2026-03-01,-350.00,Кофейня Зерно

    sfera:       Дата;Сумма;Описание
                 01.03.2026;-1 200,50;Магазин Лента

    sfera_split: Дата;Описание;Приход;Расход
                 01.03.2026;Зарплата;85 000,00;

Колонки ищутся по названию без учёта регистра и пробелов по краям, лишние игнорируются.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, replace
from decimal import Decimal
from pathlib import Path
from typing import Iterator

from ledger.clock import Clock, SystemClock
from ledger.errors import StatementError, StatementRowError, UnknownFormatError, ValidationError
from ledger.models import Transaction, parse_amount, to_money
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

_GROUP_SEPARATORS = "   "  # пробел, неразрывный пробел, узкий неразрывный пробел
_SFERA_DATE = re.compile(r"[0-9]{2}\.[0-9]{2}\.[0-9]{4}")
_SFERA_AMOUNT = re.compile(
    "(?P<sign>[+-]?)"
    "(?P<int>[0-9]{1,3}(?:[" + _GROUP_SEPARATORS + "][0-9]{3})+|[0-9]+)"
    "(?:,(?P<frac>[0-9]+))?"
)


@dataclass(frozen=True)
class _Format:
    delimiter: str
    columns: tuple[str, ...]  # нормализованные имена обязательных колонок


_FORMATS = {
    "nova": _Format(",", ("date", "amount", "description")),
    "sfera": _Format(";", ("дата", "сумма", "описание")),
    "sfera_split": _Format(";", ("дата", "описание", "приход", "расход")),
}


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError]


def normalize_description(text: str) -> str:
    """Нормализация описания для сравнения (та же, что в правилах категоризации)."""
    return normalize_text(text)


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store.

    fmt=None — формат определяется по заголовку. Нераспознанный заголовок или
    несовпадение с fmt — UnknownFormatError, store не меняется.
    Транзакции, которые уже есть в store, пропускаются (duplicates): для каждой
    пары (дата, сумма, описание) первые min(k, n) строк файла, где k — число уже
    сохранённых, а n — число в файле, считаются дублями.
    strict=True: первая ошибочная строка — StatementRowError, store не меняется.
    Иначе ошибочные строки попадают в errors, остальные импортируются.
    Запись в store одна, пачкой: либо все строки, либо ни одной.
    """
    clock = clock or SystemClock()
    imported_at = clock.now()
    text, encoding = _read_text(path)
    name, cols, header_line = _recognize(text, fmt)
    spec = _FORMATS[name]

    known = Counter(_dedup_key(tx) for tx in store.all())
    pending: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0
    for line_no, fields, csv_error in _records(text, spec.delimiter):
        if line_no <= header_line:
            continue
        try:
            if csv_error is not None:
                raise StatementError(f"malformed record: {csv_error}", line_no=line_no)
            if _is_blank(fields):
                continue
            tx = _parse_record(name, cols, fields, line_no, imported_at)
        except StatementError as exc:
            if strict:
                raise StatementRowError(exc.message, line_no=exc.line_no) from exc
            errors.append(RowError(line_no=exc.line_no, message=exc.message))
            continue
        key = _dedup_key(tx)
        if known[key] > 0:
            known[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = replace(tx, category=category)
        pending.append(tx)

    if pending:
        store.add_many(pending)
    logger.info("imported %d transactions from %s (%s)", len(pending), path, name)
    return ImportResult(
        format=name,
        encoding=encoding,
        added=len(pending),
        duplicates=duplicates,
        errors=errors,
    )


def detect_format(path: str | os.PathLike[str]) -> str:
    """Возвращает "nova", "sfera" или "sfera_split" по заголовку файла."""
    text, _ = _read_text(path)
    return _recognize(text, None)[0]


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Импортирует выписку «Новы» в store и возвращает число добавленных транзакций.

    Строгий режим: при ошибке в строке ничего не записывается.
    """
    result = import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    )
    return result.added


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    data = Path(path).read_bytes()
    try:
        text, encoding = data.decode("utf-8"), "utf-8"
    except UnicodeDecodeError:
        try:
            text, encoding = data.decode("cp1251"), "cp1251"
        except UnicodeDecodeError as exc:
            raise StatementError(f"cannot decode {path}: neither utf-8 nor cp1251") from exc
    if text.startswith("﻿"):
        text = text[1:]
    return text, encoding


class _Lines:
    """Построчный итератор по тексту, который считает прочитанные физические строки."""

    def __init__(self, text: str) -> None:
        self._fh = io.StringIO(text, newline="")
        self.count = 0

    def __iter__(self) -> "_Lines":
        return self

    def __next__(self) -> str:
        line = self._fh.readline()
        if not line:
            raise StopIteration
        self.count += 1
        return line


def _records(text: str, delimiter: str) -> Iterator[tuple[int, list[str] | None, str | None]]:
    """Отдаёт (номер первой строки записи, поля, текст ошибки csv или None)."""
    lines = _Lines(text)
    reader = csv.reader(lines, delimiter=delimiter)
    while True:
        line_no = lines.count + 1
        try:
            fields = next(reader)
        except StopIteration:
            return
        except csv.Error as exc:
            yield line_no, None, str(exc)
        else:
            yield line_no, fields, None


def _header(text: str, delimiter: str) -> tuple[int, list[str]] | None:
    """Первая непустая запись файла — заголовок. None, если её нет или она не читается."""
    for line_no, fields, csv_error in _records(text, delimiter):
        if csv_error is not None:
            return None
        if not _is_blank(fields):
            return line_no, fields
    return None


def _recognize(text: str, fmt: str | None) -> tuple[str, dict[str, int], int]:
    """Возвращает (имя формата, колонка -> индекс, номер строки заголовка)."""
    if fmt is not None and fmt not in _FORMATS:
        raise UnknownFormatError(f"unknown format {fmt!r}")
    candidates = [fmt] if fmt is not None else list(_FORMATS)

    matched: list[tuple[str, dict[str, int], int]] = []
    missing: dict[str, list[str]] = {}
    header_line = None
    for name in candidates:
        spec = _FORMATS[name]
        head = _header(text, spec.delimiter)
        if head is None:
            continue
        line_no, names = head
        header_line = line_no if header_line is None else min(header_line, line_no)
        cols: dict[str, int] = {}
        for idx, col in enumerate(names):
            cols.setdefault(normalize_text(col), idx)
        absent = [col for col in spec.columns if col not in cols]
        if absent:
            missing[name] = absent
        else:
            matched.append((name, cols, line_no))

    if len(matched) == 1:
        return matched[0]
    if header_line is None:
        raise UnknownFormatError("empty file: no header line")
    if fmt is not None:
        absent = ", ".join(missing[fmt])
        raise UnknownFormatError(
            f"header does not match format {fmt!r}: missing columns: {absent}",
            line_no=header_line,
        )
    if not matched:
        raise UnknownFormatError("unrecognized header", line_no=header_line)
    names = ", ".join(name for name, _, _ in matched)
    raise UnknownFormatError(f"header matches several formats: {names}", line_no=header_line)


def _is_blank(fields: list[str]) -> bool:
    return all(not f.strip() for f in fields)


def _dedup_key(tx: Transaction) -> tuple[dt.date, Decimal, str]:
    return (tx.date, tx.amount, normalize_description(tx.description))


def _parse_record(
    name: str,
    cols: dict[str, int],
    fields: list[str],
    line_no: int,
    imported_at: dt.datetime,
) -> Transaction:
    def cell(col: str) -> str:
        idx = cols[col]
        if idx >= len(fields):
            raise StatementError("not enough fields", line_no=line_no)
        return fields[idx].strip()

    if name == "nova":
        date = _iso_date(cell("date"), line_no)
        amount = _checked(parse_amount, cell("amount"), line_no)
    elif name == "sfera":
        date = _ru_date(cell("дата"), line_no)
        amount = _sfera_amount(cell("сумма"), line_no)
    else:
        date = _ru_date(cell("дата"), line_no)
        amount = _split_amount(cell("приход"), cell("расход"), line_no)
    description = cell("description" if name == "nova" else "описание")
    try:
        return Transaction(
            date=date,
            amount=amount,
            description=description,
            imported_at=imported_at,
        )
    except ValidationError as exc:
        raise StatementError(str(exc), line_no=line_no) from exc


def _iso_date(text: str, line_no: int) -> dt.date:
    try:
        return dt.date.fromisoformat(text)
    except ValueError as exc:
        raise StatementError(f"invalid date {text!r}", line_no=line_no) from exc


def _ru_date(text: str, line_no: int) -> dt.date:
    if not _SFERA_DATE.fullmatch(text):
        raise StatementError(f"invalid date {text!r}, expected DD.MM.YYYY", line_no=line_no)
    try:
        return dt.datetime.strptime(text, "%d.%m.%Y").date()
    except ValueError as exc:
        raise StatementError(f"invalid date {text!r}", line_no=line_no) from exc


def _checked(parse, text: str, line_no: int):
    try:
        return parse(text)
    except ValidationError as exc:
        raise StatementError(str(exc), line_no=line_no) from exc


def _sfera_amount(text: str, line_no: int) -> Decimal:
    """Сумма «Сферы»: знак необязателен, тысячи пробелом, дробная часть через запятую."""
    return _decimal(text, line_no, signed=True)


def _split_amount(income: str, expense: str, line_no: int) -> Decimal:
    """Суммы sfera_split без знака; заполнена ровно одна колонка, 0,00 — как пусто."""
    inc = _optional_amount(income, line_no)
    exp = _optional_amount(expense, line_no)
    if inc is None and exp is None:
        raise StatementError("no amount: one of 'приход', 'расход' must be filled", line_no=line_no)
    if inc is not None and exp is not None:
        raise StatementError("both 'приход' and 'расход' are filled", line_no=line_no)
    return inc if inc is not None else -exp


def _optional_amount(text: str, line_no: int) -> Decimal | None:
    if not text:
        return None
    value = _decimal(text, line_no, signed=False)
    return None if value == 0 else value


def _decimal(text: str, line_no: int, *, signed: bool) -> Decimal:
    match = _SFERA_AMOUNT.fullmatch(text)
    if match is None:
        raise StatementError(f"invalid amount {text!r}", line_no=line_no)
    if match["sign"] and not signed:
        raise StatementError(f"sign is not allowed in amount {text!r}", line_no=line_no)
    whole = re.sub(f"[{_GROUP_SEPARATORS}]", "", match["int"])
    frac = match["frac"]
    raw = f"{match['sign']}{whole}" + (f".{frac}" if frac is not None else "")
    try:
        return to_money(Decimal(raw))
    except ValidationError as exc:
        raise StatementError(str(exc), line_no=line_no) from exc

"""Правила автоматической категоризации."""

from __future__ import annotations

import json
import logging
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable

from ledger.errors import ValidationError
from ledger.models import Transaction

logger = logging.getLogger(__name__)

_KINDS = ("any", "income", "expense")


def normalize_text(text: str) -> str:
    """Приводит текст к виду для сравнения.

    Обрезает пробелы по краям, любые последовательности пробельных символов
    заменяет одним пробелом, приводит к нижнему регистру через casefold()
    и заменяет "ё" на "е". Так сравниваются описания операций везде в проекте;
    сами описания при этом хранятся как есть.
    """
    return " ".join(text.split()).casefold().replace("ё", "е")


@dataclass(frozen=True)
class Rule:
    """Если description содержит pattern (после normalize_text) — категория category.

    kind ограничивает правило приходами ("income") или расходами ("expense").
    """

    pattern: str
    category: str
    kind: str = "any"

    def __post_init__(self) -> None:
        if not self.pattern.strip():
            raise ValidationError("rule pattern must be non-empty")
        if not self.category.strip():
            raise ValidationError("rule category must be non-empty")
        if self.kind not in _KINDS:
            raise ValidationError(f"rule kind must be one of {_KINDS}, got {self.kind!r}")

    def matches(self, tx: Transaction) -> bool:
        if self.kind == "income" and tx.amount < 0:
            return False
        if self.kind == "expense" and tx.amount > 0:
            return False
        return normalize_text(self.pattern) in normalize_text(tx.description)


class Categorizer:
    """Применяет правила по порядку; побеждает первое подходящее."""

    def __init__(self, rules: Iterable[Rule]) -> None:
        self._rules = list(rules)

    @property
    def rules(self) -> list[Rule]:
        return list(self._rules)

    def categorize(self, tx: Transaction) -> str | None:
        for rule in self._rules:
            if rule.matches(tx):
                logger.debug("rule %r matched %r", rule.pattern, tx.description)
                return rule.category
        return None


def load_rules(path: str | os.PathLike[str]) -> Categorizer:
    """Загружает правила из JSON: [{"pattern": ..., "category": ..., "kind": ...}]."""
    try:
        raw = json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise ValidationError(f"cannot read rules from {path}: {exc}") from exc
    if not isinstance(raw, list):
        raise ValidationError("rules file must contain a list")
    rules = []
    for item in raw:
        try:
            rules.append(Rule(item["pattern"], item["category"], item.get("kind", "any")))
        except (KeyError, TypeError, AttributeError) as exc:
            raise ValidationError(f"bad rule {item!r}") from exc
    return Categorizer(rules)

"""Модели предметной области и денежные суммы.

Все суммы в проекте — Decimal с двумя знаками после запятой.
"""

from __future__ import annotations

import datetime as dt
import re
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from typing import Any

from ledger.errors import ValidationError

UNCATEGORIZED = "uncategorized"

CENT = Decimal("0.01")

_PLAIN_AMOUNT = re.compile(r"^[+-]?\d+(\.\d{1,2})?$")


def to_money(value: Decimal) -> Decimal:
    """Проверяет сумму и приводит её к двум знакам после запятой.

    Принимает только Decimal: float и int-строки сюда попадать не должны.
    Больше двух значащих знаков после запятой — ошибка, а не округление.
    """
    if not isinstance(value, Decimal):
        raise ValidationError(f"amount must be Decimal, got {type(value).__name__}")
    if not value.is_finite():
        raise ValidationError(f"amount must be finite, got {value}")
    quantized = value.quantize(CENT)
    if quantized != value:
        raise ValidationError(f"amount has more than 2 decimal places: {value}")
    return quantized


def parse_amount(text: str) -> Decimal:
    """Разбирает сумму вида '-1234.50' (точка, без разделителей тысяч)."""
    cleaned = text.strip()
    if not _PLAIN_AMOUNT.match(cleaned):
        raise ValidationError(f"invalid amount: {text!r}")
    try:
        return to_money(Decimal(cleaned))
    except InvalidOperation as exc:  # pragma: no cover - регулярка уже отсекла мусор
        raise ValidationError(f"invalid amount: {text!r}") from exc


def format_amount(amount: Decimal) -> str:
    """Форматирует сумму для людей: '-1 234.50'."""
    sign = "-" if amount < 0 else ""
    whole, frac = f"{abs(amount):.2f}".split(".")
    groups = []
    while whole:
        groups.insert(0, whole[-3:])
        whole = whole[:-3]
    return f"{sign}{' '.join(groups)}.{frac}"


@dataclass(frozen=True)
class Transaction:
    """Одна операция по счёту.

    amount < 0 — расход, amount > 0 — приход. Идентификатор назначает хранилище.
    """

    date: dt.date
    amount: Decimal
    description: str
    category: str | None = None
    imported_at: dt.datetime | None = None
    id: int | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.date, dt.date) or isinstance(self.date, dt.datetime):
            raise ValidationError(f"date must be datetime.date, got {self.date!r}")
        amount = to_money(self.amount)
        if amount == 0:
            raise ValidationError("amount must be non-zero")
        object.__setattr__(self, "amount", amount)
        if not isinstance(self.description, str) or not self.description.strip():
            raise ValidationError("description must be a non-empty string")
        if self.category is not None and not self.category.strip():
            raise ValidationError("category must be None or a non-empty string")

    @property
    def is_expense(self) -> bool:
        return self.amount < 0

    @property
    def month(self) -> tuple[int, int]:
        return (self.date.year, self.date.month)

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "date": self.date.isoformat(),
            "amount": str(self.amount),
            "description": self.description,
            "category": self.category,
            "imported_at": self.imported_at.isoformat() if self.imported_at else None,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "Transaction":
        imported_at = data.get("imported_at")
        return cls(
            id=data.get("id"),
            date=dt.date.fromisoformat(data["date"]),
            amount=Decimal(data["amount"]),
            description=data["description"],
            category=data.get("category"),
            imported_at=dt.datetime.fromisoformat(imported_at) if imported_at else None,
        )

"""Хранилища транзакций.

MemoryStore держит всё в памяти, JsonFileStore дополнительно сохраняет
состояние в JSON-файл после каждого изменения (атомарно, через временный файл).
"""

from __future__ import annotations

import json
import logging
import os
import tempfile
from dataclasses import replace
from pathlib import Path
from typing import Iterable

from ledger.errors import StorageError
from ledger.models import Transaction

logger = logging.getLogger(__name__)


class MemoryStore:
    """Хранилище в памяти."""

    def __init__(self) -> None:
        self._items: list[Transaction] = []
        self._next_id = 1

    def all(self) -> list[Transaction]:
        return list(self._items)

    def get(self, tx_id: int) -> Transaction:
        for tx in self._items:
            if tx.id == tx_id:
                return tx
        raise StorageError(f"transaction {tx_id} not found")

    def add(self, tx: Transaction) -> Transaction:
        """Добавляет одну транзакцию и возвращает её с назначенным id."""
        return self.add_many([tx])[0]

    def add_many(self, txs: Iterable[Transaction]) -> list[Transaction]:
        """Добавляет пачку транзакций целиком: либо все, либо ни одной."""
        batch = list(txs)
        for tx in batch:
            if not isinstance(tx, Transaction):
                raise StorageError(f"not a Transaction: {tx!r}")
            if tx.id is not None:
                raise StorageError(f"transaction already has id {tx.id}")
        stored = []
        next_id = self._next_id
        for tx in batch:
            stored.append(replace(tx, id=next_id))
            next_id += 1
        self._commit(self._items + stored, next_id)
        logger.debug("added %d transactions", len(stored))
        return stored

    def update_category(self, tx_id: int, category: str | None) -> Transaction:
        items = []
        updated = None
        for tx in self._items:
            if tx.id == tx_id:
                updated = replace(tx, category=category)
                items.append(updated)
            else:
                items.append(tx)
        if updated is None:
            raise StorageError(f"transaction {tx_id} not found")
        self._commit(items, self._next_id)
        return updated

    def _commit(self, items: list[Transaction], next_id: int) -> None:
        self._items = items
        self._next_id = next_id


class JsonFileStore(MemoryStore):
    """Хранилище в JSON-файле. Файл создаётся при первой записи."""

    def __init__(self, path: str | os.PathLike[str]) -> None:
        super().__init__()
        self.path = Path(path)
        if self.path.exists():
            self._load()

    def _load(self) -> None:
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
            self._items = [Transaction.from_dict(d) for d in data["transactions"]]
            self._next_id = int(data["next_id"])
        except (OSError, ValueError, KeyError, TypeError) as exc:
            raise StorageError(f"cannot read {self.path}: {exc}") from exc
        logger.debug("loaded %d transactions from %s", len(self._items), self.path)

    def _commit(self, items: list[Transaction], next_id: int) -> None:
        payload = {
            "next_id": next_id,
            "transactions": [tx.to_dict() for tx in items],
        }
        text = json.dumps(payload, ensure_ascii=False, indent=2)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=self.path.parent, prefix=".ledger-", suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                fh.write(text)
            os.replace(tmp, self.path)
        except OSError as exc:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise StorageError(f"cannot write {self.path}: {exc}") from exc
